namespace ghidra.app.plugin.core.symtable.dnd;







using ghidra.program.model.symbol;

public class SymbolTransferable : Transferable {

	private static readonly DataFlavor[] FLAVORS = new DataFlavor[] { SymbolDataFlavor.DATA_FLAVOR };
	private List<Symbol> symbols;
	private Component source;

	public SymbolTransferable(Component source, List<Symbol> symbols) {
		this.source = Objects.requireNonNull(source);
		this.symbols = Objects.requireNonNull(symbols);
	}

	/* @Override */
	public object getTransferData(DataFlavor flavor)
    {

		if (!SymbolDataFlavor.DATA_FLAVOR.equals(flavor)) {
			throw new UnsupportedFlavorException(flavor);
		}

		return new SymbolTransferData(source, symbols);
	}

	/* @Override */
	public DataFlavor[] getTransferDataFlavors() {
		return FLAVORS;
	}

	/* @Override */
	public bool isDataFlavorSupported(DataFlavor flavor) {
		foreach (DataFlavor f in FLAVORS) {
			if (f.equals(flavor)) {
				return true;
			}
		}
		return false;
	}
}
